from collections import Counter
def comps(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if not seen[i][j]:
                c=g[i][j]; st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==c:
                            seen[ny][nx]=True; st.append((ny,nx))
                out.append((c,cells))
    return out
def transform(g,thresh=4):
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    H,W=len(g),len(g[0]); out=[[bg]*W for _ in range(H)]
    for c,cells in comps(g):
        if c!=bg and len(cells)>=thresh:
            ys=[y for y,_ in cells]; xs=[x for _,x in cells]
            for y in range(min(ys),max(ys)+1):
                for x in range(min(xs),max(xs)+1): out[y][x]=c
    return out
